# hypothesis: A decorator typed with Callable[Concatenate[int, P], R] that injects a leading int removes that parameter from the wrapped signature, and forwarding *args and **kwargs through P preserves the remaining keyword-only parameters.
from collections.abc import Callable
from typing import Concatenate, ParamSpec, TypeVar, assert_type, reveal_type

P = ParamSpec('P')
R = TypeVar('R')


def inject_retries(func: Callable[Concatenate[int, P], R]) -> Callable[P, R]:
    def wrapper(*args: P.args, **kwargs: P.kwargs) -> R:
        return func(3, *args, **kwargs)
    return wrapper


@inject_retries
def fetch(retries: int, url: str, *, timeout: float = 1.0) -> str:
    return f'{url}:{retries}:{timeout}'


text = fetch('http://a', timeout=2.5)
assert_type(text, str)
reveal_type(fetch)
print(text)
print(fetch('http://b'))


def call_bad() -> None:
    fetch(3, 'x')  # expect-error


try:
    call_bad()
except TypeError:
    print('rejected')
